import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [user] = useState({ name: 'Dr. Rodrigo', office: 'Rodrigo Advocacia', plano: 'Premium Cloud' });
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v10_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [promptIA, setPromptIA] = useState('');
  const [respostaIA, setRespostaIA] = useState('');

  useEffect(() => {
    localStorage.setItem('juris_v10_data', JSON.stringify(processos));
  }, [processos]);

  // Função Simula IA para Petições
  const gerarTextoIA = () => {
    setRespostaIA("Processando com Inteligência Jurídica...");
    setTimeout(() => {
      setRespostaIA(`[MINUTA GERADA] Exmo. Sr. Dr. Juiz... Com base no pedido de "${promptIA}", informamos que o fundamento legal baseia-se no Art. 319 do CPC/15. Verifique os prazos de 15 dias úteis no seu painel.`);
    }, 1500);
  };

  const totalHonorarios = processos.reduce((a, b) => a + Number(b.valor), 0);

  return (
    <div style={s.app}>
      <aside style={s.sidebar}>
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Inteligência BI</div>
          <div style={s.navLink(tab === 'ia')} onClick={() => setTab('ia')}>🤖 Assistente IA</div>
          <div style={s.navLink(tab === 'financeiro')} onClick={() => setTab('financeiro')}>💰 Fluxo de Caixa</div>
        </nav>
        <div style={s.planoCard}>
          <div style={{fontSize: '10px', color: COLORS.gold}}>STATUS DO SERVIDOR</div>
          <div style={{fontSize: '12px', fontWeight: 'bold', color: COLORS.success}}>ONLINE • CRYPTO SECURE</div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header}>
          <div>
            <h2 style={{margin: 0}}>{user.office}</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Sistema Operacional v10.0</p>
          </div>
          <div style={s.avatarGroup}>
            <div style={s.avatar}>R</div>
            <span style={{fontSize: '14px'}}>{user.name}</span>
          </div>
        </header>

        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Patrimônio Total" value={`R$ ${totalHonorarios.toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Projeção 12 meses" value={`R$ ${(totalHonorarios * 1.2).toLocaleString()}`} color={COLORS.accent} />
            <StatCard label="Eficiência de Prazos" value="98%" color={COLORS.gold} />
            
            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h3 style={{marginTop: 0}}>Análise de Performance Mensal</h3>
              <div style={s.chartPlaceholder}>
                {[40, 70, 45, 90, 65, 80, 100].map((h, i) => (
                  <div key={i} style={s.bar(h)} title={`Mês ${i+1}`} />
                ))}
              </div>
            </div>
          </div>
        )}

        {tab === 'ia' && (
          <div style={s.card}>
            <h3>🤖 Redator Jurídico Inteligente</h3>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Descreva o que precisa (ex: Contestação Cível) e a IA estruturará o texto.</p>
            <textarea 
              style={s.textarea} 
              placeholder="Digite o objeto da petição ou dúvida jurídica..."
              value={promptIA}
              onChange={(e) => setPromptIA(e.target.value)}
            />
            <button style={s.btnIA} onClick={gerarTextoIA}>GERAR ESTRUTURA JURÍDICA</button>
            
            {respostaIA && (
              <div style={s.iaBox}>
                {respostaIA}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '11px', fontWeight: 'bold'}}>{label}</div>
    <div style={{fontSize: '26px', fontWeight: 'bold', color: color, marginTop: '10px'}}>{value}</div>
  </div>
);

const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: 'Inter, sans-serif' },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '30px 20px' },
  brand: { fontSize: '22px', fontWeight: 'bold', color: COLORS.accent, display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '40px' },
  brandIcon: { width: '30px', height: '30px', backgroundColor: COLORS.accent, borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' },
  nav: { flex: 1 },
  navLink: (active) => ({ padding: '14px', borderRadius: '10px', cursor: 'pointer', marginBottom: '8px', color: active ? COLORS.accent : COLORS.muted, backgroundColor: active ? '#38bdf811' : 'transparent', fontSize: '14px' }),
  planoCard: { padding: '15px', backgroundColor: '#000', borderRadius: '12px', border: `1px solid ${COLORS.border}` },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', marginBottom: '40px', alignItems: 'center' },
  avatarGroup: { display: 'flex', alignItems: 'center', gap: '10px' },
  avatar: { width: '35px', height: '35px', backgroundColor: COLORS.gold, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'black', fontWeight: 'bold' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
  card: { backgroundColor: COLORS.card, padding: '25px', borderRadius: '20px', border: `1px solid ${COLORS.border}` },
  chartPlaceholder: { height: '150px', display: 'flex', alignItems: 'flex-end', gap: '15px', marginTop: '20px', borderBottom: `1px solid ${COLORS.border}` },
  bar: (h) => ({ width: '100%', height: `${h}%`, backgroundColor: COLORS.accent, borderRadius: '4px 4px 0 0', opacity: 0.8 }),
  textarea: { width: '100%', height: '120px', backgroundColor: '#000', border: `1px solid ${COLORS.border}`, borderRadius: '12px', color: 'white', padding: '15px', marginTop: '10px', outline: 'none' },
  btnIA: { width: '100%', padding: '15px', backgroundColor: COLORS.accent, color: '#000', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop: '15px' },
  iaBox: { marginTop: '20px', padding: '20px', backgroundColor: '#020617', border: `1px dashed ${COLORS.accent}`, borderRadius: '12px', color: COLORS.accent, fontSize: '14px', lineHeight: '1.6' }
};
